import random
import sys
import time

def draw_board(board):
    for row in board:
        print(" ".join(row))

def get_move(board):
    while True:
        try:
            move = input("Enter your move (row column): ").split()
            row, col = int(move[0]), int(move[1])
            if 0 <= row < len(board) and 0 <= col < len(board[row]) and board[row][col] == " ":
                return row, col
            else:
                print("Invalid move. Try again.")
        except ValueError:
            print("Invalid input. Try again.")

def check_win(board):
    for row in board:
        if all(cell == "X" for cell in row):
            return True
        if all(cell == "O" for cell in row):
            return True
    for col in range(len(board)):
        if all(board[row][col] == "X" for row in range(len(board))):
            return True
        if all(board[row][col] == "O" for row in range(len(board))):
            return True
    if all(board[i][i] == "X" for i in range(len(board))) or all(board[i][len(board) - 1 - i] == "X" for i in range(len(board))):
        return True
    if all(board[i][i] == "O" for i in range(len(board))) or all(board[i][len(board) - 1 - i] == "O" for i in range(len(board))):
        return True
    return False

def main():
    board = [[" " for _ in range(3)] for _ in range(3)]
    current_player = "X"
    while True:
        draw_board(board)
        row, col = get_move(board)
        board[row][col] = current_player
        if check_win(board):
            print(f"{current_player} wins!")
            break
        current_player = "O" if current_player == "X" else "X"

if __name__ == "__main__":
