import curses
import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.keypad(True)
    stdscr.timeout(120)

    snake = [(10, 10)]
    direction = curses.KEY_RIGHT
    food = (15, 15)
    score = 0

    def draw_snake():
        stdscr.clear()
        for pos in snake:
            stdscr.addch(pos[0], pos[1], '#')
        stdscr.addch(food[0], food[1], '*')
        stdscr.addstr(0, 0, f"Score: {score}")
        stdscr.refresh()

    def move_snake():
        head = snake[0]
        new_head = (head[0] + direction[0], head[1] + direction[1])

        if new_head == food:
            score += 1
            food = (new_head[0] + (new_head[0] - head[0]) % 15, new_head[1] + (new_head[1] - head[1]) % 15)
        else:
            snake.pop()

        snake.insert(0, new_head)

    def handle_input():
        key = stdscr.getch()
        if key == ord('q'):
            return False
        elif key == curses.KEY_UP and direction != curses.KEY_DOWN:
            direction = curses.KEY_UP
        elif key == curses.KEY_DOWN and direction != curses.KEY_UP:
            direction = curses.KEY_DOWN
        elif key == curses.KEY_LEFT and direction != curses.KEY_RIGHT:
            direction = curses.KEY_LEFT
        elif key == curses.KEY_RIGHT and direction != curses.KEY_LEFT:
            direction = curses.KEY_RIGHT
        return True

    while True:
        if not handle_input():
            break
        move_snake()
        draw_snake()
        time.sleep(0.1)

if __name__ == "__main__":
    curses.wrapper(main)

import curses
import random

def main(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(1)
    stdscr.timeout(100)

    snake = [(0, 0)]
    direction = curses.KEY_RIGHT
    food = random.choice([(i, j) for i in range(10) for j in range(10)])
    score = 0

    while True:
        key = stdscr.getch()
        if key == curses.KEY_UP and direction != curses.KEY_DOWN:
            direction = curses.KEY_UP
        elif key == curses.KEY_DOWN and direction != curses.KEY_UP:
            direction = curses.KEY_DOWN
        elif key == curses.KEY_LEFT and direction != curses.KEY_RIGHT:
            direction = curses.KEY_LEFT
        elif key == curses.KEY_RIGHT and direction != curses.KEY_LEFT:
            direction = curses.KEY_RIGHT
        elif key == ord('q'):
            break

        new_head = (snake[0][0] + direction[0], snake[0][1] + direction[1])
        if new_head == food:
            food = random.choice([(i, j) for i in range(10) for j in range(10)])
            score += 1
        else:
            snake.pop()

        if new_head in snake[:-1] or new_head[0] < 0 or new_head[0] >= 10 or new_head[1] < 0 or new_head[1] >= 10:
            break

        snake.insert(0, new_head)

        stdscr.clear()
        for i in range(10):
            for j in range(10):
                if (i, j) == food:
                    stdscr.addch(i, j, curses.ACS_PI)
                elif (i, j) in snake:
                    stdscr.addch(i, j, curses.ACS_CKBOARD)
                else:
                    stdscr.addch(i, j, ' ')
        stdscr.addstr(0, 0, f"Score: {score}")

if __name__ == "__main__":
    curses.wrapper(main)
